CREATE OR REPLACE FUNCTION public.staff_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT role FROM public.user_roles WHERE user_id=auth.uid()),'') $$;
CREATE OR REPLACE FUNCTION public.staff_area() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE public.staff_role() WHEN 'External Logistics Officer' THEN 'external' WHEN 'Internal Logistics Officer' THEN 'internal' WHEN 'Transport Officer' THEN 'transport' WHEN 'Dispatcher' THEN 'transport' WHEN 'Finance Officer' THEN 'finance' WHEN 'Accountant' THEN 'finance' ELSE '' END $$;
CREATE OR REPLACE FUNCTION public.staff_department() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.staff_role() LIKE '%Logistics%' THEN 'logistics' WHEN public.staff_role() IN ('Transport Manager','Transport Officer','Dispatcher') THEN 'transport' WHEN public.staff_role() IN ('Finance Manager','Finance Officer','Accountant') THEN 'finance' ELSE '' END $$;